public void updateEncryptionType(Constants.EncryptionType encryptionType) {
    this.encryptionType = encryptionType;

    // The views are not created yet, the new encryption type will be applied in onCreateView()
    if (desc == null || selection == null || selectionMapping == null)
        return;

    Constants.AuthMethod selectedMethod = selectionMapping.get(selection.getSelectedItemPosition());

    if (encryptionType == Constants.EncryptionType.KEYSTORE) {
        desc.setText(R.string.intro_slide3_desc_keystore);

        // Authentication is optional with the KeyStore, so don't force the user to set
        // a password / PIN (which would block the navigation with a warning), unless
        // credentials have already been entered.
        if ((selectedMethod == Constants.AuthMethod.PASSWORD || selectedMethod == Constants.AuthMethod.PIN)
                && passwordInput.getText().toString().isEmpty()
                && passwordConfirm.getText().toString().isEmpty())
            selection.setSelection(selectionMapping.indexOfValue(Constants.AuthMethod.NONE));
    } else if (encryptionType == Constants.EncryptionType.PASSWORD) {
        desc.setText(R.string.intro_slide3_desc_password);

        // Only a password or a PIN can be used to encrypt the data
        if (selectedMethod != Constants.AuthMethod.PASSWORD && selectedMethod != Constants.AuthMethod.PIN)
            selection.setSelection(selectionMapping.indexOfValue(Constants.AuthMethod.PASSWORD));
    }

    // Make sure a stale warning from a previous encryption type doesn't stick around
    if (authWarnings != null && authWarnings.getVisibility() == View.VISIBLE)
        updateNavigation();
}

    // Set the default authentication method based on the currently selected encryption
    // type: it is mandatory for the password-based encryption and optional otherwise.
    if (encryptionType == Constants.EncryptionType.PASSWORD)
        selection.setSelection(selectionMapping.indexOfValue(Constants.AuthMethod.PASSWORD));
    else
        selection.setSelection(selectionMapping.indexOfValue(Constants.AuthMethod.NONE));

    // The encryption type might have been changed before this view was created,
    // so make sure the description reflects the current selection.
    updateEncryptionType(encryptionType);

    return root;
}

